8	async function findQualityTable(ctx: AssertionContext): Promise<string | null> {
9	  const pgCheck = await ctx.pg.query(`
10	    SELECT table_schema, table_name FROM information_schema.tables
11	    WHERE table_name LIKE '%quality%' OR table_name LIKE '%dq%' OR table_name LIKE '%check%'
12	    LIMIT 1
13	  `);
14	  if (pgCheck.rows.length > 0) {
15	    return `${pgCheck.rows[0].table_schema}.${pgCheck.rows[0].table_name}`;
16	  }
17	  return null;
18	}
