20	export async function detects_null_event_ids(ctx: AssertionContext): Promise<AssertionResult> {
21	  const nullCheck = await ctx.pg.query(
22	    "SELECT count(*) AS n FROM raw.events WHERE event_id IS NULL",
23	  );
24	  const nullCount = Number(nullCheck.rows[0]?.n ?? 0);
25	
26	  const table = await findQualityTable(ctx);
27	  if (!table) {
28	    return { passed: false, message: "Quality table not found.", details: {} };
29	  }
30	
31	  const results = await ctx.pg.query(`SELECT * FROM ${table}`);
32	  const resultText = JSON.stringify(results.rows).toLowerCase();
33	  const passed = nullCount === 5 && (resultText.includes("null") || resultText.includes("missing"));
34	  return {
35	    passed,
36	    message: passed ? "Detects null event IDs." : `Expected 5 nulls and quality flag; nullCount=${nullCount}.`,
37	    details: { nullCount, table },
38	  };
39	}
